  1	/**
  2	 * Tests for WP-001: Knowledge Handler Foundations
  3	 *
  4	 * Covers:
  5	 * - handleListKnowledge (AC-1 through AC-7)
  6	 * - parseKnowledgeId    (AC-8)
  7	 * - findInsightById     (AC-9)
  8	 *
  9	 * Uses real temp directories and KnowledgeStoreManager to seed fixture data.
 10	 */
 11	
 12	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
 13	import { mkdtemp, rm } from 'fs/promises';
 14	import { join } from 'path';
 15	import { tmpdir } from 'os';
 16	
 17	import {
 18	  handleListKnowledge,
 19	  handleUpdateKnowledge,
 20	  handleDeleteKnowledge,
 21	  handlePromoteKnowledge,
 22	  handleMoveKnowledge,
 23	  ApiError,
 24	} from '../../gui/api.js';
 25	import { KnowledgeStoreManager } from '../../src/storage/knowledge-store.js';
 26	import type { Insight } from '../../src/schema/knowledge.js';
 27	
 28	// ---------------------------------------------------------------------------
 29	// Helpers
 30	// ---------------------------------------------------------------------------
 31	
 32	/** Build a minimal valid insight input (no id). */
 33	function makeInsightInput(overrides: Partial<Omit<Insight, 'id'>> = {}): Omit<Insight, 'id'> {
 34	  return {
 35	    scope: 'global',
 36	    title: 'Default title',
 37	    content: 'Default content',
 38	    category: 'general',
 39	    tags: [],
 40	    source: 'test',
 41	    created_at: '2026-01-01T00:00:00Z',
 42	    confidence: 0.8,
 43	    ...overrides,
 44	  };
 45	}
 46	
 47	// ---------------------------------------------------------------------------
 48	// Suite
 49	// ---------------------------------------------------------------------------
 50	
 51	describe('WP-001 Knowledge Handler Foundations', () => {
 52	  let ledgerRoot: string;
 53	  let manager: KnowledgeStoreManager;
 54	
 55	  beforeEach(async () => {
 56	    ledgerRoot = await mkdtemp(join(tmpdir(), 'api-knowledge-test-'));
 57	    manager = new KnowledgeStoreManager(ledgerRoot);
 58	  });
 59	
 60	  afterEach(async () => {
 61	    await rm(ledgerRoot, { recursive: true, force: true });
 62	  });
 63	
 64	  // ─── handleListKnowledge ────────────────────────────────────────────────
 65	
 66	  describe('handleListKnowledge', () => {
 67	    // AC-7: empty store returns empty array
 68	    it('AC-7: returns empty array when no insights exist', async () => {
 69	      const result = await handleListKnowledge(ledgerRoot);
 70	      expect(result).toEqual([]);
 71	    });
 72	
 73	    // AC-1: no params returns all insights from both global and project stores
 74	    it('AC-1: returns all insights from global and project stores when no params given', async () => {
 75	      await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global insight' }));
 76	      await manager.addInsight(
 77	        makeInsightInput({ scope: 'project', project_slug: 'my-project', title: 'Project insight' })
 78	      );
 79	
 80	      const result = await handleListKnowledge(ledgerRoot);
 81	      expect(result).toHaveLength(2);
 82	      const titles = result.map((i) => i.title);
 83	      expect(titles).toContain('Global insight');
 84	      expect(titles).toContain('Project insight');
 85	    });
 86	
 87	    // AC-2: scope: 'global' returns only global insights
 88	    it('AC-2: scope: global returns only global insights', async () => {
 89	      await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global A' }));
 90	      await manager.addInsight(
 91	        makeInsightInput({ scope: 'project', project_slug: 'proj', title: 'Project B' })
 92	      );
 93	
 94	      const result = await handleListKnowledge(ledgerRoot, { scope: 'global' });
 95	      expect(result).toHaveLength(1);
 96	      expect(result[0]!.scope).toBe('global');
 97	      expect(result[0]!.title).toBe('Global A');
 98	    });
 99	
100	    // AC-3: scope: 'project' + project_slug returns only that project's insights

621	    expect(globalInsight.id).toBe(1);
622	    expect(projectInsight.id).toBe(1);
623	
624	    // Delete only the project-scoped insight
625	    const result = await handleDeleteKnowledge(ledgerRoot, '1', 'project', 'proj-a');
626	    expect(result).toBeNull();
627	
628	    // Project insight is gone
629	    const projectInsights = await manager.listInsights({ scope: 'project', project_slug: 'proj-a' });
630	    expect(projectInsights).toHaveLength(0);
631	
632	    // Global insight is untouched
633	    const globalInsights = await manager.listInsights({ scope: 'global' });
634	    expect(globalInsights).toHaveLength(1);
635	    expect(globalInsights[0]!.title).toBe('Global id=1');
636	  });
637	});
638	
639	// ---------------------------------------------------------------------------
640	// WP-005: handlePromoteKnowledge
641	// ---------------------------------------------------------------------------
642	
643	describe('WP-005 handlePromoteKnowledge', () => {
644	  let ledgerRoot: string;
645	  let manager: KnowledgeStoreManager;
646	
647	  beforeEach(async () => {
648	    ledgerRoot = await mkdtemp(join(tmpdir(), 'api-knowledge-promote-test-'));
649	    manager = new KnowledgeStoreManager(ledgerRoot);
650	  });
651	
652	  afterEach(async () => {
653	    await rm(ledgerRoot, { recursive: true, force: true });
654	  });
655	
656	  // AC-1: converts a project-scoped insight to global scope and returns the new insight
657	  it('AC-1: converts a project-scoped insight to global scope and returns the new insight', async () => {
658	    const original = await manager.addInsight(
659	      makeInsightInput({ scope: 'project', project_slug: 'my-proj', title: 'To promote' })
660	    );
661	
662	    const promoted = await handlePromoteKnowledge(
663	      ledgerRoot,
664	      String(original.id),
665	      'project',
666	      'my-proj'
667	    );
668	
669	    expect(promoted.scope).toBe('global');
670	    expect(promoted.title).toBe('To promote');
671	    expect(promoted.project_slug).toBeUndefined();
672	  });
673	
674	  // AC-2: removes the original project-scoped insight after promotion
675	  it('AC-2: removes the original project-scoped insight after promotion', async () => {
676	    const original = await manager.addInsight(
677	      makeInsightInput({ scope: 'project', project_slug: 'my-proj', title: 'Will be removed' })
678	    );
679	
680	    await handlePromoteKnowledge(ledgerRoot, String(original.id), 'project', 'my-proj');
681	
682	    const remaining = await manager.listInsights({ scope: 'project', project_slug: 'my-proj' });
683	    expect(remaining).toHaveLength(0);
684	  });
685	
686	  // AC-3: throws VALIDATION_ERROR if the insight is already global
687	  it('AC-3: throws VALIDATION_ERROR if scope is "global" (already global)', async () => {
688	    const global = await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global' }));
689	
690	    await expect(
691	      handlePromoteKnowledge(ledgerRoot, String(global.id), 'global')
692	    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
693	  });
694	
695	  // AC-4: throws NOT_FOUND for unknown id in the specified scope
696	  it('AC-4: throws NOT_FOUND for unknown id in the specified scope', async () => {
697	    await expect(
698	      handlePromoteKnowledge(ledgerRoot, '99999', 'project', 'my-proj')
699	    ).rejects.toMatchObject({ code: 'NOT_FOUND' });
700	  });
701	
702	  it('AC-4: throws NOT_FOUND when id exists in a different project', async () => {
703	    const insight = await manager.addInsight(
704	      makeInsightInput({ scope: 'project', project_slug: 'proj-a', title: 'Proj A' })
705	    );
706	
707	    await expect(
708	      handlePromoteKnowledge(ledgerRoot, String(insight.id), 'project', 'proj-b')
709	    ).rejects.toMatchObject({ code: 'NOT_FOUND' });
710	  });
711	
712	  // AC-5: promotes the correct insight when two stores share the same numeric id (scope disambiguation)
713	  it('AC-5: promotes the correct insight when two stores share the same numeric id', async () => {
714	    // Both stores start at next_id=1, so their first insight will have id=1
715	    const globalInsight = await manager.addInsight(
716	      makeInsightInput({ scope: 'global', title: 'Global id=1' })
717	    );
718	    const projectInsight = await manager.addInsight(
719	      makeInsightInput({ scope: 'project', project_slug: 'proj-a', title: 'Project id=1' })
720	    );
721	
722	    expect(globalInsight.id).toBe(1);
723	    expect(projectInsight.id).toBe(1);
724	
725	    // Promote the project insight (id=1, scope=project)
726	    const promoted = await handlePromoteKnowledge(ledgerRoot, '1', 'project', 'proj-a');
727	
728	    // The promoted insight is the project-scoped one
729	    expect(promoted.scope).toBe('global');
730	    expect(promoted.title).toBe('Project id=1');
731	
732	    // The original project insight is gone
733	    const projInsights = await manager.listInsights({ scope: 'project', project_slug: 'proj-a' });
734	    expect(projInsights).toHaveLength(0);
735	
736	    // The global insight is untouched (different object despite same original id)
737	    const globalInsights = await manager.listInsights({ scope: 'global' });
738	    // Two global insights now: the original and the promoted copy
739	    expect(globalInsights).toHaveLength(2);
740	    const titles = globalInsights.map((i) => i.title);
741	    expect(titles).toContain('Global id=1');
742	    expect(titles).toContain('Project id=1');
743	  });
744	
745	  // Validation: missing scope throws VALIDATION_ERROR
746	  it('throws VALIDATION_ERROR when scope is missing', async () => {
747	    await expect(
748	      handlePromoteKnowledge(ledgerRoot, '1', undefined, 'my-proj')
749	    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
750	  });
751	
752	  // Validation: project scope without project_slug throws VALIDATION_ERROR
753	  it('throws VALIDATION_ERROR when scope is "project" but project_slug is missing', async () => {
754	    await expect(
755	      handlePromoteKnowledge(ledgerRoot, '1', 'project')
756	    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
757	  });
758	
759	  // Validation: non-integer id throws VALIDATION_ERROR
760	  it('throws VALIDATION_ERROR for non-integer id', async () => {
761	    await expect(
762	      handlePromoteKnowledge(ledgerRoot, 'abc', 'project', 'my-proj')
763	    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
764	  });
765	
766	  // Returned insight has a new ID (different from the source insight)
767	  it('returned insight has a different id than the original', async () => {
768	    // Add a global insight first so the global store's next_id starts at 2
769	    await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Pre-existing global' }));
770	
771	    const original = await manager.addInsight(
772	      makeInsightInput({ scope: 'project', project_slug: 'my-proj', title: 'Will be promoted' })
773	    );
774	
775	    const promoted = await handlePromoteKnowledge(
776	      ledgerRoot,
777	      String(original.id),
778	      'project',
779	      'my-proj'
780	    );
781	
782	    // The original had id=1 in the project store; the promoted copy should get id=2 in global store
783	    expect(promoted.id).not.toBe(original.id);
784	  });
785	});
786	
787	// ---------------------------------------------------------------------------
788	// WP-005: handleMoveKnowledge
789	// ---------------------------------------------------------------------------
790	
791	describe('WP-005 handleMoveKnowledge', () => {
792	  let ledgerRoot: string;
793	  let manager: KnowledgeStoreManager;
794	
795	  beforeEach(async () => {
796	    ledgerRoot = await mkdtemp(join(tmpdir(), 'api-knowledge-move-test-'));
797	    manager = new KnowledgeStoreManager(ledgerRoot);
798	  });
799	
800	  afterEach(async () => {
801	    await rm(ledgerRoot, { recursive: true, force: true });
802	  });
803	
804	  // AC-6: moves a global insight to a named project and returns the new insight
805	  it('AC-6: moves a global insight to a named project and returns the new insight', async () => {
806	    const global = await manager.addInsight(
807	      makeInsightInput({ scope: 'global', title: 'Will move to project' })
808	    );
809	
810	    const moved = await handleMoveKnowledge(ledgerRoot, String(global.id), {
811	      source_scope: 'global',
812	      project_slug: 'target-proj',
813	    });
814	
815	    expect(moved.scope).toBe('project');
816	    expect(moved.project_slug).toBe('target-proj');
817	    expect(moved.title).toBe('Will move to project');
818	  });
819	
820	  it('AC-6: removes the original global insight after moving to project', async () => {
821	    const global = await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Move me' }));
822	
823	    await handleMoveKnowledge(ledgerRoot, String(global.id), {
824	      source_scope: 'global',
825	      project_slug: 'target-proj',
826	    });
827	
828	    const globalInsights = await manager.listInsights({ scope: 'global' });
829	    expect(globalInsights).toHaveLength(0);
830	  });
831	
832	  // AC-7: moves a project insight to a different project and returns the new insight
833	  it('AC-7: moves a project insight to a different project and returns the new insight', async () => {
834	    const original = await manager.addInsight(
835	      makeInsightInput({ scope: 'project', project_slug: 'proj-a', title: 'Move between projects' })
836	    );
837	
838	    const moved = await handleMoveKnowledge(ledgerRoot, String(original.id), {
839	      source_scope: 'project',
840	      source_project_slug: 'proj-a',
841	      project_slug: 'proj-b',
842	    });
843	
844	    expect(moved.scope).toBe('project');
845	    expect(moved.project_slug).toBe('proj-b');
846	    expect(moved.title).toBe('Move between projects');
847	
848	    // Original is gone
849	    const projAInsights = await manager.listInsights({ scope: 'project', project_slug: 'proj-a' });
850	    expect(projAInsights).toHaveLength(0);
